import { buildMannequin, MANNEQUIN_GENERATOR, type Mesh } from "../body/mannequin";
import type { BodyPassport } from "../passport/passport";

/**
 * TRANSFORMATION SEQUENCES (engine `bi-morph@1`)
 *
 * Correspondence: every snapshot's body mesh is generated by the same
 * parametric generator (fixed rings × segments, canonical A-pose, floor at 0),
 * so vertex i means the same anatomical location in every snapshot. We verify
 * the topology signature before interpolating and refuse incompatible meshes.
 *
 * Frames that coincide with a snapshot are ACTUAL SCAN states; every other frame
 * is an INTERPOLATED VISUAL STATE — never a measurement.
 */
export const MORPH_ENGINE = "bi-morph@1";

export type BodyMeshRecord = { generator: string; topology: string; mesh: Mesh };
export const topologyOf = (m: Mesh) => `${MANNEQUIN_GENERATOR}:${m.vertices.length}v:${m.faces.length}f:${m.faces.map((f) => f.length).join("").length}`;

export function bodyMesh(p: BodyPassport): BodyMeshRecord {
  const mesh = buildMannequin(p);
  return { generator: MANNEQUIN_GENERATOR, topology: topologyOf(mesh), mesh };
}

export function compatible(a: BodyMeshRecord, b: BodyMeshRecord) {
  if (a.topology !== b.topology) return false;
  for (let i = 0; i < a.mesh.faces.length; i += 97) if (a.mesh.faces[i].join() !== b.mesh.faces[i].join()) return false;
  return true;
}

export function lerpPositions(a: Mesh, b: Mesh, t: number, out?: Float32Array): Float32Array {
  const n = a.vertices.length;
  const o = out ?? new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    const p = a.vertices[i];
    const q = b.vertices[i];
    o[i * 3] = p[0] + (q[0] - p[0]) * t;
    o[i * 3 + 1] = p[1] + (q[1] - p[1]) * t;
    o[i * 3 + 2] = p[2] + (q[2] - p[2]) * t;
  }
  return o;
}

export type SequenceKey = { snapshotId: number | string; at: string; passport: BodyPassport; mesh: BodyMeshRecord; label: string; hypothetical?: boolean };
export type FrameState = { positions: Float32Array; kind: "ACTUAL SCAN" | "INTERPOLATED VISUAL STATE" | "HYPOTHETICAL SIMULATION"; from: SequenceKey; to: SequenceKey; alpha: number; dateLabel: string };

/**
 * @param keys       chronological keyframes (≥ 1)
 * @param holdFrac   fraction of each segment spent holding on the actual scan
 */
export function makeSequence(keys: SequenceKey[], holdFrac = 0.3) {
  if (!keys.length) throw new Error("no keyframes");
  for (let i = 1; i < keys.length; i++) if (!compatible(keys[0].mesh, keys[i].mesh)) throw new Error(`Snapshot ${keys[i].snapshotId} mesh topology differs — refusing to interpolate incompatible meshes`);
  const segs = Math.max(1, keys.length - 1);
  const buf = new Float32Array(keys[0].mesh.mesh.vertices.length * 3);
  return {
    keys,
    /** u ∈ [0,1] across the whole sequence. */
    frameAt(u: number): FrameState {
      if (keys.length === 1) return { positions: lerpPositions(keys[0].mesh.mesh, keys[0].mesh.mesh, 0, buf), kind: keys[0].hypothetical ? "HYPOTHETICAL SIMULATION" : "ACTUAL SCAN", from: keys[0], to: keys[0], alpha: 0, dateLabel: keys[0].label };
      const x = Math.min(segs - 1e-9, Math.max(0, u * segs));
      const i = Math.floor(x);
      const local = x - i;
      // hold on each actual scan at the start of its segment (and the last at the end)
      const h = holdFrac / 2;
      let alpha = local < h ? 0 : local > 1 - h ? 1 : (local - h) / (1 - 2 * h);
      if (u >= 1) alpha = 1;
      const s = alpha * alpha * (3 - 2 * alpha); // smoothstep
      const from = keys[i];
      const to = keys[i + 1];
      const actual = alpha === 0 || alpha === 1;
      const hyp = (alpha === 0 && from.hypothetical) || (alpha === 1 && to.hypothetical) || (!actual && (from.hypothetical || to.hypothetical));
      return {
        positions: lerpPositions(from.mesh.mesh, to.mesh.mesh, s, buf),
        kind: hyp ? "HYPOTHETICAL SIMULATION" : actual ? "ACTUAL SCAN" : "INTERPOLATED VISUAL STATE",
        from, to, alpha,
        dateLabel: actual ? (alpha === 0 ? from.label : to.label) : `${from.label} → ${to.label}`,
      };
    },
  };
}

/** A clearly-labelled hypothetical body: the given passport with measurement deltas applied. */
export function hypotheticalPassport(p: BodyPassport, deltasMm: Record<string, number>): BodyPassport {
  return {
    ...p,
    profileId: p.profileId,
    displayName: p.displayName + " (HYPOTHETICAL)",
    hardware: { ...p.hardware, simulated: true },
    measurements: p.measurements.map((m) => (deltasMm[m.id] ? { ...m, value: m.value + deltasMm[m.id], method: "estimated", procedure: "HYPOTHETICAL scenario — not a measurement", status: "unvalidated" } : m)),
  };
}
